window.TEMPLATE_HTML = "<!DOCTYPE html>\n<!--\n================================================================================\n  TomTom customer email notification template\n================================================================================\n  Source of truth : Figma – TomTom Playbook Web tools, frame \"TomTom email template\"\n                    https://www.figma.com/design/So2GOMuscJx4Y2TwBiy3Hj/TomTom---Playbook---Web---tools?node-id=27358-55660\n  How to use      : https://tomtom.atlassian.net/wiki/spaces/cet/pages/2735080120/How+to+use+the+email+template\n  Questions       : Radovan Tadic (template structure), Jo Hetherington or Miguel Sioco (adoption, exceptions)\n\n  THE TEMPLATE HAS FOUR SECTIONS\n    1. TomTom logo         LOCKED    – do not change\n    2. Text body           EDITABLE  – change the text, links and button\n    3. Support pathways    LOCKED    – do not change\n    4. Footer              LOCKED    – do not change\n\n  Look for these markers in the code:\n    <!== ✏️ EDITABLE ... ==>   you can change what is between the start and end markers\n    <!== 🔒 LOCKED ... ==>     keep as it is\n\n  RULES FOR THE TEXT BODY\n    - Name the product in the body (not in the header). The header only says TomTom.\n    - Say plainly what changed, what the reader needs to do, and by when.\n    - One primary button. Remove the bullet list if you have no extra links.\n    - Never put passwords, API keys or other credentials in an email.\n    - Replace every [bracketed placeholder]. Check that every link works.\n\n  BEFORE YOU SEND\n    - Fill in the <title> (use your subject line) and the preheader text below.\n    - Host the logo PNG on a public HTTPS URL and replace the logo src.\n    - Test on mobile, dark mode, Outlook (desktop) and Gmail. Check contrast.\n\n  This file is email-safe: single-column tables, inline styles, live text,\n  no scripts, no SVG. Keep it that way when you edit it.\n================================================================================\n-->\n<html lang=\"en\" xmlns=\"http://www.w3.org/1999/xhtml\" xmlns:v=\"urn:schemas-microsoft-com:vml\" xmlns:o=\"urn:schemas-microsoft-com:office:office\">\n<head>\n  <meta charset=\"utf-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <meta http-equiv=\"X-UA-Compatible\" content=\"IE=edge\">\n  <meta name=\"x-apple-disable-message-reformatting\">\n  <meta name=\"format-detection\" content=\"telephone=no, date=no, address=no, email=no, url=no\">\n  <!-- The template is designed for a light background. These ask email apps not to recolor it. -->\n  <meta name=\"color-scheme\" content=\"light\">\n  <meta name=\"supported-color-schemes\" content=\"light\">\n\n  <!-- ✏️ EDITABLE: use your email subject line here -->\n  <title>[Subject line]</title>\n\n  <!--[if mso]>\n  <noscript><xml><o:OfficeDocumentSettings><o:PixelsPerInch>96</o:PixelsPerInch></o:OfficeDocumentSettings></xml></noscript>\n  <style>\n    /* Outlook desktop ignores web fonts: fall back to Arial. */\n    table, td, p, a, span, li { font-family: Arial, Helvetica, sans-serif !important; }\n  </style>\n  <![endif]-->\n\n  <!-- 🔒 LOCKED: email fallback fonts (Gilroy and Proxima Nova are used when installed) -->\n  <!--[if !mso]><!-->\n  <link href=\"https://fonts.googleapis.com/css2?family=Figtree:wght@400&family=Plus+Jakarta+Sans:wght@700&display=swap\" rel=\"stylesheet\">\n  <!--<![endif]-->\n\n  <style>\n    :root { color-scheme: light; supported-color-schemes: light; }\n    body { margin: 0; padding: 0; width: 100% !important; background-color: #ffffff; -webkit-text-size-adjust: 100%; -ms-text-size-adjust: 100%; }\n    table { border-collapse: collapse; mso-table-lspace: 0pt; mso-table-rspace: 0pt; }\n    img { border: 0; outline: none; text-decoration: none; -ms-interpolation-mode: bicubic; display: block; }\n    a { color: inherit; }\n    a[x-apple-data-detectors] { color: inherit !important; text-decoration: none !important; }\n\n    /* Small screens: tighter side padding, smaller title. */\n    @media only screen and (max-width: 620px) {\n      .tt-container { width: 100% !important; }\n      .tt-pad { padding-left: 24px !important; padding-right: 24px !important; }\n      .tt-header { padding-top: 32px !important; padding-bottom: 32px !important; }\n      .tt-h1 { font-size: 28px !important; line-height: 36px !important; }\n    }\n  </style>\n</head>\n\n<body style=\"margin:0; padding:0; background-color:#ffffff;\">\n\n  <!-- ✏️ EDITABLE: preheader – the preview line shown after the subject in the inbox (about 40–90 characters) -->\n  <div style=\"display:none; max-height:0; overflow:hidden; mso-hide:all; font-size:1px; line-height:1px; color:#ffffff; opacity:0;\">\n    [Preheader: one sentence that adds to the subject line.]\n  </div>\n  <!-- Spacer that stops inbox previews pulling in body text after the preheader. -->\n  <div style=\"display:none; max-height:0; overflow:hidden; mso-hide:all;\">&#847;&zwnj;&nbsp;&#847;&zwnj;&nbsp;&#847;&zwnj;&nbsp;&#847;&zwnj;&nbsp;&#847;&zwnj;&nbsp;&#847;&zwnj;&nbsp;&#847;&zwnj;&nbsp;&#847;&zwnj;&nbsp;&#847;&zwnj;&nbsp;&#847;&zwnj;&nbsp;</div>\n\n  <table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" style=\"background-color:#ffffff;\">\n    <tr>\n      <td align=\"center\" style=\"padding:0;\">\n\n        <!--[if mso]><table role=\"presentation\" width=\"600\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td><![endif]-->\n        <table role=\"presentation\" class=\"tt-container\" width=\"600\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" style=\"width:600px; max-width:600px; background-color:#ffffff;\">\n\n          <!-- ======================================================================\n               🔒 LOCKED · SECTION 1 · TomTom logo\n               Do not change the logo, its size (125 × 24) or the spacing.\n               Do not add a product name here – name the product in the text body.\n               Replace src with the hosted URL of assets/tomtom-logo@4x.png.\n               ====================================================================== -->\n          <tr data-section=\"logo\">\n            <td class=\"tt-pad tt-header\" style=\"padding:40px 48px 40px 48px;\">\n              <img src=\"assets/tomtom-logo@4x.png\" width=\"125\" height=\"24\" alt=\"TomTom\" style=\"display:block; width:125px; height:24px; border:0;\">\n            </td>\n          </tr>\n          <!-- 🔒 END LOCKED · SECTION 1 -->\n\n          <!-- ======================================================================\n               ✏️ EDITABLE · SECTION 2 · Text body\n               Change the text, the links and the button label and URL.\n               Keep the styles (fonts, sizes, colors, spacing) as they are.\n               ====================================================================== -->\n          <tr data-section=\"body\">\n            <td class=\"tt-pad\" style=\"padding:0 48px 16px 48px;\">\n              <table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\">\n\n                <!-- Title: the update in a few words -->\n                <tr>\n                  <td style=\"padding:0 0 32px 0;\">\n                    <h1 class=\"tt-h1\" style=\"margin:0; font-family:'Gilroy','Plus Jakarta Sans',Arial,Helvetica,sans-serif; font-weight:700; font-size:32px; line-height:40px; letter-spacing:-0.32px; color:#000000;\">\n                      [Your update at a glance]\n                    </h1>\n                  </td>\n                </tr>\n\n                <!-- Greeting and introduction -->\n                <tr>\n                  <td style=\"padding:0 0 16px 0; font-family:'Proxima Nova','Figtree',Arial,Helvetica,sans-serif; font-size:16px; line-height:24px; color:#5c5c5c;\">\n                    Hello [First name],\n                  </td>\n                </tr>\n                <tr>\n                  <td style=\"padding:0 0 16px 0; font-family:'Proxima Nova','Figtree',Arial,Helvetica,sans-serif; font-size:16px; line-height:24px; color:#5c5c5c;\">\n                    There&rsquo;s an update to [product name, e.g. Move]. [A short explanation of what has changed and why it matters to you.]\n                  </td>\n                </tr>\n\n                <!-- Subheading -->\n                <tr>\n                  <td style=\"padding:0 0 16px 0;\">\n                    <h2 style=\"margin:0; font-family:'Gilroy','Plus Jakarta Sans',Arial,Helvetica,sans-serif; font-weight:700; font-size:20px; line-height:24px; color:#000000;\">\n                      [What you need to know]\n                    </h2>\n                  </td>\n                </tr>\n\n                <!-- Key detail and optional links (remove the list if you don't need it) -->\n                <tr>\n                  <td style=\"padding:0 0 32px 0; font-family:'Proxima Nova','Figtree',Arial,Helvetica,sans-serif; font-size:16px; line-height:24px; color:#5c5c5c;\">\n                    <p style=\"margin:0;\">[The essential detail, relevant date or next step. Keep this paragraph focused on the information you need to take action.</p>\n                    <ul style=\"margin:0; padding:0 0 0 24px;\">\n                      <li style=\"margin:0; font-size:16px; line-height:24px; color:#5c5c5c;\"><a href=\"https://example.com/link-1\" style=\"color:#5c5c5c; text-decoration:underline;\">Link option 1</a></li>\n                      <li style=\"margin:0; font-size:16px; line-height:24px; color:#5c5c5c;\"><a href=\"https://example.com/link-2\" style=\"color:#5c5c5c; text-decoration:underline;\">Link option 2</a>]</li>\n                    </ul>\n                  </td>\n                </tr>\n\n                <!-- Primary button: change the label and both href values (Outlook uses the first one) -->\n                <tr>\n                  <td style=\"padding:0;\">\n                    <!--[if mso]>\n                    <v:roundrect xmlns:v=\"urn:schemas-microsoft-com:vml\" xmlns:w=\"urn:schemas-microsoft-com:office:word\" href=\"https://example.com/action\" style=\"height:44px; v-text-anchor:middle; width:120px;\" arcsize=\"50%\" stroke=\"f\" fillcolor=\"#000000\">\n                      <w:anchorlock/>\n                      <center style=\"color:#ffffff; font-family:Arial,Helvetica,sans-serif; font-size:14px; font-weight:bold;\">Button</center>\n                    </v:roundrect>\n                    <![endif]-->\n                    <!--[if !mso]><!-->\n                    <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\">\n                      <tr>\n                        <td style=\"border-radius:40px; background-color:#000000;\">\n                          <a href=\"https://example.com/action\" style=\"display:inline-block; padding:12px 20px; border-radius:40px; background-color:#000000; font-family:'Gilroy','Plus Jakarta Sans',Arial,Helvetica,sans-serif; font-weight:700; font-size:14px; line-height:20px; color:#ffffff; text-decoration:none;\">Button</a>\n                        </td>\n                      </tr>\n                    </table>\n                    <!--<![endif]-->\n                  </td>\n                </tr>\n\n              </table>\n            </td>\n          </tr>\n          <!-- ✏️ END EDITABLE · SECTION 2 -->\n\n          <!-- ======================================================================\n               🔒 LOCKED · SECTION 3 · Support pathways and sign-off\n               Every email ends by pointing to the Help Center, so customers always\n               have one official place to ask. Do not replace it with a team mailbox.\n               ====================================================================== -->\n          <tr data-section=\"support\">\n            <td class=\"tt-pad\" style=\"padding:0 48px 40px 48px;\">\n              <table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\">\n                <tr>\n                  <td style=\"padding:0 0 4px 0; font-family:'Proxima Nova','Figtree',Arial,Helvetica,sans-serif; font-size:16px; line-height:24px; color:#5c5c5c;\">\n                    [If you have any questions or need for support,]\n                  </td>\n                </tr>\n                <tr>\n                  <td style=\"padding:4px 0 36px 0; font-size:14px; line-height:20px;\">\n                    <a href=\"https://support.tomtom.com\" style=\"font-family:'Gilroy','Plus Jakarta Sans',Arial,Helvetica,sans-serif; font-weight:700; font-size:14px; line-height:20px; color:#000000; text-decoration:none;\">Visit the Help Center</a>\n                  </td>\n                </tr>\n                <tr>\n                  <td style=\"padding:0; font-family:'Proxima Nova','Figtree',Arial,Helvetica,sans-serif; font-size:16px; line-height:24px; color:#5c5c5c;\">\n                    Thank you,<br>\n                    The TomTom team\n                  </td>\n                </tr>\n              </table>\n            </td>\n          </tr>\n          <!-- 🔒 END LOCKED · SECTION 3 -->\n\n          <!-- ======================================================================\n               🔒 LOCKED · SECTION 4 · Footer\n               Only fill in [Year] and [Legal entity].\n               ====================================================================== -->\n          <tr data-section=\"footer\">\n            <td class=\"tt-pad\" style=\"padding:0 48px 32px 48px;\">\n              <table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\">\n                <!-- Divider: 1px #E5E5E5 line -->\n                <tr>\n                  <td style=\"padding:0 0 24px 0;\">\n                    <table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\">\n                      <tr><td style=\"height:2px; line-height:2px; font-size:0;\">&nbsp;</td></tr>\n                      <tr><td style=\"height:1px; line-height:1px; font-size:0; border-top:1px solid #e5e5e5;\">&nbsp;</td></tr>\n                    </table>\n                  </td>\n                </tr>\n                <tr>\n                  <td style=\"padding:4px 0 12px 0; font-size:12px; line-height:16px;\">\n                    <a href=\"https://www.tomtom.com/privacy/\" style=\"font-family:'Gilroy','Plus Jakarta Sans',Arial,Helvetica,sans-serif; font-weight:700; font-size:12px; line-height:16px; color:#000000; text-decoration:none;\">Privacy Policy</a>\n                  </td>\n                </tr>\n                <tr>\n                  <td style=\"padding:0 0 8px 0; font-family:'Proxima Nova','Figtree',Arial,Helvetica,sans-serif; font-size:12px; line-height:16px; color:#959595;\">\n                    &copy; [Year] [Legal entity]. All Rights Reserved.\n                  </td>\n                </tr>\n                <tr>\n                  <td style=\"padding:0; font-family:'Proxima Nova','Figtree',Arial,Helvetica,sans-serif; font-size:12px; line-height:16px; color:#959595;\">\n                    Please do not reply to this email.\n                  </td>\n                </tr>\n              </table>\n            </td>\n          </tr>\n          <!-- 🔒 END LOCKED · SECTION 4 -->\n\n        </table>\n        <!--[if mso]></td></tr></table><![endif]-->\n\n      </td>\n    </tr>\n  </table>\n</body>\n</html>\n";
